(() => {
  const summary=document.querySelector('.order-summary');if(!summary)return;
  let choice;try{choice=JSON.parse(sessionStorage.getItem('jtm-flight-choice')||'')}catch{}if(!choice?.flight)return;
  const clean=value=>String(value||'').replace(/\b(Bandar Udara|Airport|Internasional|International)\b/gi,'').replace(/\s+/g,' ').trim();
  const code=(airport,fallback)=>String(airport?.id||airport?.iata||fallback||'').toUpperCase();
  const formatTime=value=>{const date=new Date(String(value||'').replace(' ','T'));return Number.isNaN(date.valueOf())?'—':new Intl.DateTimeFormat('id-ID',{dateStyle:'medium',timeStyle:'short'}).format(date)};
  const sector=(title,flight,from,to)=>{const legs=flight?.flights||[];const first=legs[0]||{},last=legs.at(-1)||first;return `<section class="checkout-sector"><h3>${title}</h3><b>${clean(first.departure_airport?.name)||from} (${code(first.departure_airport,from)}) → ${clean(last.arrival_airport?.name)||to} (${code(last.arrival_airport,to)})</b>${legs.map(leg=>`<div class="checkout-leg"><strong>${clean(leg.departure_airport?.name)} (${code(leg.departure_airport,from)}) → ${clean(leg.arrival_airport?.name)} (${code(leg.arrival_airport,to)})</strong><span>${leg.airline||''} ${leg.flight_number||''} · ${formatTime(leg.departure_airport?.time)} – ${formatTime(leg.arrival_airport?.time)}</span></div>`).join('')}</section>`};
  const currency=choice.search?.currency||'IDR',price=new Intl.NumberFormat('id-ID',{style:'currency',currency,maximumFractionDigits:0}).format(Number(choice.flight.price||0)),isReturn=Boolean(choice.returnFlight);
  summary.innerHTML=`<h2>Ringkasan penerbangan</h2><p class="checkout-summary-intro">Periksa seluruh rute dan jadwal sebelum mengirim permintaan.</p><div class="checkout-itineraries">${sector('Pergi',choice.flight,choice.search.origin,choice.search.destination)}${isReturn?sector('Pulang',choice.returnFlight,choice.search.destination,choice.search.origin):''}</div><hr><div class="order-total"><span>Harga indikatif ${isReturn?'pergi–pulang':'per orang'}</span><b>${price}</b></div><small>Harga ditampilkan dalam ${currency} dan sudah termasuk estimasi pajak. Harga serta ketersediaan dikonfirmasi sebelum tiket diterbitkan.</small>`;
  document.head.insertAdjacentHTML('beforeend','<style>.checkout-summary-intro{margin:0 0 16px;color:#526b8e;font-size:.84rem}.checkout-itineraries{display:grid;gap:13px}.checkout-sector{padding:14px;border:1px solid #dbe3ec;border-radius:9px;background:#f8fbff}.checkout-sector h3{margin:0 0 8px;color:#1e3a8a;font-size:.88rem}.checkout-sector>b{display:block;line-height:1.45}.checkout-leg{padding:10px 0 0;margin-top:10px;border-top:1px solid #dbe3ec}.checkout-leg strong,.checkout-leg span{display:block;font-size:.8rem;line-height:1.45}.checkout-leg span{color:#526b8e}.phone-country{border:1px solid #cbd5e1!important;border-radius:8px!important;background:#fff!important;font:500 .9rem DM Sans!important;padding:10px!important}</style>');
  const phone=document.querySelector('[name="phone"]');if(phone){phone.inputMode='numeric';phone.pattern='[0-9]*';phone.addEventListener('input',event=>event.target.value=event.target.value.replace(/\D/g,''))}
})();
